function normalize(text) {
  if (typeof text !== 'string') {
    text = String(text);
  }
  return text.normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
}

function tokenize(text) {
  const normalized = normalize(text);
  const tokens = [];
  let current = '';
  for (let i = 0; i < normalized.length; i++) {
    const ch = normalized[i];
    if (/[a-z0-9]/.test(ch)) {
      current += ch;
    } else if (ch === "'") {
      // Apostrophe acts as a separator, so flush any pending token.
      if (current) {
        tokens.push(current);
        current = '';
      }
    } else {
      // Any other character (including accented letters) is a separator.
      if (current) {
        tokens.push(current);
        current = '';
      }
    }
  }
  if (current) {
    tokens.push(current);
  }
  return tokens;
}

function analyze(text) {
  const tokens = tokenize(text);
  const frequencies = {};
  const unique = [];
  const seen = {};
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (Object.prototype.hasOwnProperty.call(frequencies, token)) {
      frequencies[token] += 1;
    } else {
      frequencies[token] = 1;
    }
    if (!Object.prototype.hasOwnProperty.call(seen, token)) {
      seen[token] = true;
      unique.push(token);
    }
  }
  return {
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies,
    summary: tokens.length + ' tokens; ' + unique.length + ' unique'
  };
}

